import React from 'react';
import MainHeading from '../../Components/Heading/MainHeading';
import NavBar from '../../Components/NavBar/NavBar';
import bgVideo from "./back.mp4"



function Home() {
  return (
    <>
    <div className="relative w-full h-screen">
    {/* Background video */}
    <video
      className="absolute top-0 left-0 w-full h-full object-cover"
      autoPlay
      loop
      muted
      >
      <source src={bgVideo} type="video/mp4" />
      Your browser does not support the video tag.
    </video>

    {/* Overlay content */}
    <div className="relative font-poppins z-10  items-center justify-center flex w-full h-full bg-black bg-opacity-50">
      <NavBar  />
      <h1 className="text-white text-7xl font-bold">Explore The Solar System</h1>
      <p className="mt-4 text-lg">Journey through the wonders of the Sun, planets, and beyond.</p>
    </div>
  </div>
      </>
  );
}

export default Home;
